-- Course intake Run & Validate, PR #872: Platform Admin vertical-feature correction, 4 Nov 2026.
-- Depends on 20261104610000 and 20261104630000. Generated by CLI, ordered after scope dependency.
-- Replaces: nothing (isolated browser bridges; no existing function definition is edited).
-- Retires: nothing.
-- No reader, scheduler, admission rule, consumer API shape or operational switch changes.
-- The bridge selects only inside the existing approved top-AU scope, using the existing plan and its ordering.

-- Read-only contract reconciliation against Pilot metadata on 4 Nov 2026. Fail rather than adapt a changed authority silently.
do $guard$
declare d record;
begin
 for d in select * from (values
 ('security.intake_dates_plan_v2(uuid[],integer)','8e3e11c3b78e4e52ea0709e48a666ff6'),
 ('security.intake_dates_apply_v1(integer,uuid[])','d47fbe685ae62287264a1909c988e9d6'),
 ('security.run_now_cohort_create_v1(text,uuid,text,text)','410db5ca480e038e32d12c16f66eefa9'),
 ('security.job_run_now_v1(text,text,jsonb,uuid)','cabacd4094ed138a57f6b102183eeacc'),
 ('public.admin_job_run_now_v1(text,text,jsonb)','2a5ccb9fe52041696582a8b524bc8ae2'),
 ('security.run_now_cohort_verify_v1(uuid)','9de88275d2e29a7f4c062d5319d6316d')) x(signature,expected) loop
 if md5(pg_get_functiondef(to_regprocedure(d.signature))) is distinct from d.expected then
 raise exception 'PR 872 dependency changed: %; Integration Controller must reconcile before applying',d.signature; end if;
 end loop;
end $guard$;

