create table if not exists pipeline.intake_ui_signing_key (
 singleton boolean primary key default true check(singleton), secret text not null default gen_random_uuid()::text || gen_random_uuid()::text);
comment on table pipeline.intake_ui_signing_key is 'PR #872 private preview HMAC key; never returned to clients. No consumer reads.';
insert into pipeline.intake_ui_signing_key(singleton) values(true) on conflict do nothing;
alter table pipeline.intake_ui_signing_key enable row level security;
revoke all on pipeline.intake_ui_signing_key from public,anon,authenticated;

create table if not exists pipeline.intake_ui_requests (
 cohort_id uuid primary key references pipeline.run_now_cohorts(id), requested_by uuid not null,
 preview_token text not null unique, request_key text not null unique default gen_random_uuid()::text,
 scope text not null, size integer not null, reason text not null, created_at timestamptz not null default now());
comment on table pipeline.intake_ui_requests is 'PR #872 saved browser cohort requests: caller-bound preview, immutable reason and idempotency key for refresh/recovery. Uses existing cohort and run audit; no consumer reads.';
alter table pipeline.intake_ui_requests enable row level security;
revoke all on pipeline.intake_ui_requests from public,anon,authenticated;

create or replace function security.intake_ui_scopes_v1() returns jsonb
language sql stable security definer set search_path to '' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'active_courses',n) order by n desc,md5(id::text)),'[]')
 from (select p.id,coalesce(p.display_name,p.canonical_name) name,count(c.id) n
 from catalogue.providers p join ref.countries co on co.id=p.country_id and co.iso_alpha2='AU'
 join ref.provider_types t on t.id=p.provider_type_id and t.code='university'
 join catalogue.courses c on c.provider_id=p.id and c.lifecycle_status='active'
 where p.lifecycle_status='active' group by p.id,2 order by count(c.id) desc,md5(p.id::text)
 limit security.pipeline_num_v1('run_now.cohort_top_au_universities',10)::int) u
$$;
revoke all on function security.intake_ui_scopes_v1() from public,anon,authenticated;

-- Read-only UI projection of the canonical plan. This is not an intake reader or admission implementation.
create or replace function security.intake_ui_selection_v1(p_scope text,p_size integer) returns jsonb
language plpgsql stable security definer set search_path to '' as $$
declare unis jsonb:=security.intake_ui_scopes_v1(); ids uuid[]; result jsonb; cap integer:=security.pipeline_num_v1('run_now.pilot_cap',20)::int;
begin
 if p_size is null or p_size<1 or p_size>cap then raise exception 'cohort size must be between 1 and %',cap; end if;
 if p_scope is null or not (p_scope='top-au' or exists(select 1 from jsonb_array_elements(unis) u where u->>'id'=p_scope)) then
   raise exception 'invalid scope: select within the approved top Australian universities'; end if;
 ids:=array(select c.id from catalogue.courses c where c.lifecycle_status='active' and c.provider_id in
   (select (u->>'id')::uuid from jsonb_array_elements(unis) u where p_scope='top-au' or u->>'id'=p_scope));
 with plan as materialized(select * from security.intake_dates_plan_v2(ids,security.pipeline_num_v1('run_now.cohort_scan_rows',1500)::int)),
 f as(select * from plan where outcome='filled'),
 c as(select course_id,min(provider_id::text)::uuid provider_id,
 array_remove(array[case when bool_or(new_year is not null) then 'year' end,case when bool_or(new_start is not null) then 'start_date' end,case when bool_or(new_deadline is not null) then 'application_deadline' end],null) fills,
 string_agg(distinct coalesce(start_precision,'-')||'/'||coalesce(deadline_kind,'-'),'+' order by coalesce(start_precision,'-')||'/'||coalesce(deadline_kind,'-')) pattern,
 jsonb_agg(jsonb_build_object('intake_id',intake_id,'proposal_id',proposal_id,'calendar_evidence_id',calendar_evidence_id,'calendar_url',calendar_url,
 'page_url',(select e.source_url from catalogue.course_intakes i join pipeline.evidence_artifacts e on e.id=i.evidence_id where i.id=intake_id),'periods',periods,'page_quote',page_quote,'start_quote',start_quote,'deadline_quote',deadline_quote,'deadline_kind',deadline_kind,
 'before',before_value,'planned',jsonb_build_object('year',new_year,'start_date',new_start,'application_deadline',new_deadline),'rule',rule) order by intake_id) at_selection
 from f group by course_id),
 r as(select c.*,row_number() over(partition by provider_id order by cardinality(fills) desc,md5(course_id::text)) rp,
 row_number() over(partition by pattern order by cardinality(fills) desc,md5(course_id::text)) rq from c),
 pick as(select r.*,row_number() over(order by rp,rq,cardinality(fills) desc,md5(course_id::text)) n from r)
 select jsonb_build_object('scope',p_scope,'size',p_size,'cap',cap,'scan_rows',security.pipeline_num_v1('run_now.cohort_scan_rows',1500),
 'universities',unis,'scope_courses',cardinality(ids),'rows_planned',(select count(*) from plan),
 'eligible_courses',(select count(distinct course_id) from f),'rows_eligible',(select count(*) from f),
 'skipped_by_reason',(select coalesce(jsonb_object_agg(reason,n),'{}') from(select coalesce(reason,outcome) reason,count(*) n from plan where outcome<>'filled' group by 1) x),
 'rule','Existing intake-dates-plan-v2 filled outcome: official stored page and approved calendar; most missing fields first, round-robin universities and evidence patterns; no scope widening',
 'courses',coalesce((select jsonb_agg(jsonb_build_object('course_id',p.course_id,'provider_id',p.provider_id,'pick',p.n,'pattern',p.pattern,'fills',p.fills,
 'course_title',coalesce(cc.display_title,cc.canonical_title),'provider_name',coalesce(pp.display_name,pp.canonical_name),'course_url',cc.course_url,
 'eligibility_reason','The existing intake plan found supported missing values from the stored course wording and an approved calendar; its manual-lock, same-month and admission guards remain authoritative.',
 'at_selection',p.at_selection) order by p.n) from pick p join catalogue.courses cc on cc.id=p.course_id join catalogue.providers pp on pp.id=p.provider_id where p.n<=p_size),'[]')) into result;
 return result;
end $$;
revoke all on function security.intake_ui_selection_v1(text,integer) from public,anon,authenticated;

create or replace function security.intake_ui_preview_v1(p_scope text,p_size integer) returns jsonb
language plpgsql stable security definer set search_path to '' as $$
declare s jsonb; body jsonb; signature text; expires timestamptz;
begin
 s:=security.intake_ui_selection_v1(p_scope,p_size);
 expires:=now()+make_interval(secs=>security.pipeline_num_v1('run_now.preview_seconds',600)::int);
 body:=jsonb_build_object('scope',p_scope,'size',p_size,'requester',auth.uid(),'expires_at',expires,'fingerprint',encode(extensions.digest(s::text,'sha256'),'hex'));
 select encode(extensions.hmac(body::text,secret,'sha256'),'hex') into signature from pipeline.intake_ui_signing_key;
 return s||jsonb_build_object('as_at',now(),'expires_at',expires,'token',jsonb_build_object('body',body,'signature',signature)::text);
end $$;
revoke all on function security.intake_ui_preview_v1(text,integer) from public,anon,authenticated;

create or replace function public.admin_intake_cohort_prepare_v1(p_scope text,p_size integer,p_reason text,p_preview_token text) returns jsonb
language plpgsql security definer set search_path to '' as $$
declare tok jsonb; body jsonb; sig text; s jsonb; c uuid; existing pipeline.intake_ui_requests%rowtype;
begin
 if auth.uid() is null or security.current_role_rank()<greatest(coalesce((select control_rank from pipeline.automation_catalogue where jobname='intake-dates-apply'),6),3) then
 raise exception 'your role cannot prepare this job' using errcode='42501'; end if;
 if coalesce(btrim(p_reason),'')='' then raise exception 'an audited reason is required'; end if;
 tok:=p_preview_token::jsonb; body:=tok->'body';
 select encode(extensions.hmac(body::text,secret,'sha256'),'hex') into sig from pipeline.intake_ui_signing_key;
 if sig is null or tok->>'signature' is distinct from sig or body->>'requester' is distinct from auth.uid()::text or body->>'scope' is distinct from p_scope
 or (body->>'size')::integer is distinct from p_size then raise exception 'invalid or foreign preview'; end if;
 -- Serialise preparation of the same preview; this is not the intake job's lock.
 perform pg_advisory_xact_lock(hashtextextended(p_preview_token,0)); -- fixed: token-level duplicate preparation guard
 select * into existing from pipeline.intake_ui_requests where preview_token=p_preview_token;
 if found then
 if existing.reason<>btrim(p_reason) then raise exception 'fixed cohort reason cannot change'; end if;
 return jsonb_build_object('cohort_id',existing.cohort_id,'preview_token',p_preview_token,'request_key',existing.request_key,'reason',existing.reason); end if;
 if (body->>'expires_at')::timestamptz<clock_timestamp() then raise exception 'preview expired; preview again'; end if;
 s:=security.intake_ui_selection_v1(p_scope,p_size);
 if encode(extensions.digest(s::text,'sha256'),'hex') is distinct from body->>'fingerprint' then raise exception 'selection or evidence changed; preview again'; end if;
 if jsonb_array_length(s->'courses')=0 then raise exception 'no eligible courses: inspect missing evidence and current intake rules'; end if;
 insert into pipeline.run_now_cohorts(job,label,selection_rule,selection,requested_by,reason)
 values('intake-dates-apply','Operator intake cohort',s->>'rule',s-'courses',auth.uid(),btrim(p_reason)) returning id into c;
 insert into pipeline.run_now_cohort_members(cohort_id,course_id,provider_id,pick,pattern,fills,evidence)
 select c,(m->>'course_id')::uuid,(m->>'provider_id')::uuid,(m->>'pick')::integer,m->>'pattern',array(select jsonb_array_elements_text(m->'fills')),m->'at_selection'
 from jsonb_array_elements(s->'courses') m;
 insert into pipeline.intake_ui_requests(cohort_id,requested_by,preview_token,scope,size,reason)
 values(c,auth.uid(),p_preview_token,p_scope,p_size,btrim(p_reason)) returning * into existing;
 insert into pipeline.admin_control_events(area,action,target,detail,actor)
 values('run_now','cohort_prepared','intake-dates-apply',jsonb_build_object('cohort_id',c,'selection',s-'courses'),auth.uid());
 return jsonb_build_object('cohort_id',c,'preview_token',p_preview_token,'request_key',existing.request_key,'reason',existing.reason);
end $$;
revoke all on function public.admin_intake_cohort_prepare_v1(text,integer,text,text) from public,anon;
grant execute on function public.admin_intake_cohort_prepare_v1(text,integer,text,text) to authenticated;

-- A browser request never supplies a job, reason, course list or idempotency key to this facade.
-- Serialise duplicate UI calls BEFORE entering the existing runner (its audit row is only visible at completion).
create or replace function public.admin_intake_run_now_v1(p_cohort_id uuid) returns jsonb
language plpgsql security definer set search_path to '' as $$
declare r pipeline.intake_ui_requests%rowtype;
begin
 if auth.uid() is null then raise exception 'sign in required' using errcode='42501'; end if;
 select * into r from pipeline.intake_ui_requests where cohort_id=p_cohort_id and requested_by=auth.uid();
 if not found then raise exception 'fixed request is unavailable to this operator' using errcode='42501'; end if;
 if security.current_role_rank()<coalesce((select control_rank from pipeline.automation_catalogue where jobname='intake-dates-apply'),6) then
 raise exception 'your role cannot start this job' using errcode='42501'; end if;
 if not pg_try_advisory_xact_lock(hashtextextended('intake ui request:'||p_cohort_id,0)) then -- fixed: serialise duplicate request before shared runner
 insert into pipeline.admin_control_events(area,action,target,detail,actor)
 values('run_now','duplicate_ui_request','intake-dates-apply',jsonb_build_object('cohort_id',p_cohort_id),auth.uid());
 return jsonb_build_object('state','in_progress','cohort_id',p_cohort_id,'next_action','Read the saved cohort after the in-flight request finishes; no second run was dispatched.'); end if;
 return public.admin_job_run_now_v1('intake-dates-apply',r.reason,jsonb_build_object('cohort_id',r.cohort_id,'idempotency_key',r.request_key));
end $$;
revoke all on function public.admin_intake_run_now_v1(uuid) from public,anon;
grant execute on function public.admin_intake_run_now_v1(uuid) to authenticated;

-- Require every non-null admitted scalar, including application deadline, in one consumer intake.
create or replace function security.intake_ui_values_match_v1(p_after jsonb,p_items jsonb) returns boolean
language sql immutable set search_path to '' as $$
 select case when jsonb_typeof(p_items)='array' then exists(
 select 1 from jsonb_array_elements(p_items) i where not exists(
 select 1 from jsonb_each(p_after) a where a.value<>'null'::jsonb and i->>a.key is distinct from p_after->>a.key)) else null end
$$;
revoke all on function security.intake_ui_values_match_v1(jsonb,jsonb) from public,anon,authenticated;

-- Isolated dedicated RPC follows existing admin_* patterns; no shared admin_read dispatcher edit.
create or replace function public.admin_intake_run_read_v1(p_view text,p_args jsonb default '{}') returns jsonb
language plpgsql security definer set search_path to '' as $$
declare unis jsonb; r jsonb; req pipeline.intake_ui_requests%rowtype; c uuid; rank integer:=security.current_role_rank(); blocked text;
begin
 if auth.uid() is null or rank<3 then raise exception 'Operations read permission required' using errcode='42501'; end if;
 if p_view='capabilities' then
 unis:=security.intake_ui_scopes_v1();
 blocked:=case when not exists(select 1 from pipeline.automation_catalogue where jobname='intake-dates-apply') then 'job is not catalogued'
 when not exists(select 1 from cron.job where jobname='intake-dates-apply' and active) then 'job is paused or not scheduled'
 when not coalesce((security.toolset_setting('pipeline','intake_dates.apply_enabled')#>>'{}')::boolean,false) then 'job switch is off'
 when not coalesce(security.toolset_setting('pipeline','run_now.jobs') ? 'intake-dates-apply',false) then 'job is not allowlisted' end;
 return jsonb_build_object('contract','intake-run-validate-v1','actor_id',auth.uid(),'can_run',rank>=coalesce((select control_rank from pipeline.automation_catalogue where jobname='intake-dates-apply'),6) and blocked is null,
 'control_rank',coalesce((select control_rank from pipeline.automation_catalogue where jobname='intake-dates-apply'),6),'min_size',1,
 'max_size',security.pipeline_num_v1('run_now.pilot_cap',20),'default_size',security.pipeline_num_v1('run_now.pilot_cap',20),
 'blocked_reason',blocked,'next_action',case when blocked is not null then 'An authorised operator must resolve the existing job controls; preview and saved verification remain read-only.' end,
 'scopes',jsonb_build_array(jsonb_build_object('id','top-au','label','Top '||security.pipeline_num_v1('run_now.cohort_top_au_universities',10)::int||' Australian universities by active courses'))||
 coalesce((select jsonb_agg(jsonb_build_object('id',u->>'id','label',(u->>'name')||' ('||(u->>'active_courses')||' active courses)')) from jsonb_array_elements(unis) u),'[]'),
 'universities',unis,'recent',coalesce((select jsonb_agg(x order by x.created_at desc) from
 (select cohort_id,scope,size,reason,request_key,created_at from pipeline.intake_ui_requests where requested_by=auth.uid() order by created_at desc limit security.pipeline_num_v1('run_now.history_rows',20)::int) x),'[]'),
 'diagnostic',jsonb_build_object('approved',false));
 elsif p_view='preview' then return security.intake_ui_preview_v1(p_args->>'scope',(p_args->>'size')::integer);
 elsif p_view='verify' then
 c:=(p_args->>'cohort_id')::uuid;
 select * into req from pipeline.intake_ui_requests where cohort_id=c and requested_by=auth.uid();
 if not found then raise exception 'cohort is unavailable to this operator' using errcode='42501'; end if;
 r:=security.run_now_cohort_verify_v1(c);
 -- Decorate read-back; do not alter either frozen consumer response shape or their functions.
 r:=r||jsonb_build_object('courses',coalesce((select jsonb_agg(x||jsonb_build_object(
 'course_title',(select coalesce(display_title,canonical_title) from catalogue.courses where id=(x->>'course_id')::uuid),
 'provider_name',(select coalesce(display_name,canonical_name) from catalogue.providers where id=(x->>'provider_id')::uuid),
 'publication',jsonb_build_object(
 'catalogue',case when jsonb_array_length(x->'added')>0 and not exists(select 1 from jsonb_array_elements(x->'added') a where
 not coalesce(security.intake_ui_values_match_v1(a->'after',x->'now'),false)) then 'verified' else 'unverified' end,
 'website',case when jsonb_array_length(x->'added')>0 and not exists(select 1 from jsonb_array_elements(x->'added') a where
 not coalesce(security.intake_ui_values_match_v1(a->'after',x->'website_intakes'),false)) then 'verified' else 'unverified' end,
 'zoho',case when jsonb_typeof(x->'zoho_intakes') is distinct from 'array' then 'unsupported'
 when jsonb_array_length(x->'added')>0 and not exists(select 1 from jsonb_array_elements(x->'added') a where
 not coalesce(security.intake_ui_values_match_v1(a->'after',x->'zoho_intakes'),false)) then 'verified' else 'unverified' end)) order by (x->>'pick')::int)
 from jsonb_array_elements(r->'courses') x),'[]'));
 return r||jsonb_build_object('as_at',clock_timestamp(),'saved_request',to_jsonb(req)-'preview_token'-'requested_by',
 'runs',coalesce((select jsonb_agg(jsonb_build_object('run_id',j.id,'state',j.state,'reason',j.reason,'started_at',j.started_at,'finished_at',j.finished_at,'error',j.error)||coalesce(j.result,'{}') order by j.created_at)
 from pipeline.admin_jobs j where j.kind='job_run_now' and j.args->>'cohort_id'=c::text),'[]'),
 'next_action','Compare catalogue and consumer read-backs against the fixed source evidence. Missing/unsupported consumer data is unverified, never a pass.');
 else raise exception 'unknown intake read view'; end if;
end $$;
revoke all on function public.admin_intake_run_read_v1(text,jsonb) from public,anon;
grant execute on function public.admin_intake_run_read_v1(text,jsonb) to authenticated;

insert into pipeline.component_register(kind,name,layer,area,purpose,status,replaces,introduced_in)
select kind,name,'Layer 2','Admission','PR #872 governed intake UI: '||name,'active','{}','20261105000000' from(values
 ('table','pipeline.intake_ui_signing_key'),('table','pipeline.intake_ui_requests'),
 ('function','security.intake_ui_scopes_v1'),('function','security.intake_ui_selection_v1'),('function','security.intake_ui_preview_v1'),
 ('function','security.intake_ui_values_match_v1'),('function','public.admin_intake_run_now_v1'),('function','public.admin_intake_cohort_prepare_v1'),('function','public.admin_intake_run_read_v1')) x(kind,name) on conflict do nothing;
